import 'package:flutter/material.dart'; import '../services/certificate_service.dart';
class CertificatesScreen extends StatefulWidget { const CertificatesScreen({super.key,required this.service}); final CertificateService service; @override State<CertificatesScreen> createState()=>_CertificatesScreenState(); }
class _CertificatesScreenState extends State<CertificatesScreen>{bool loading=true;List items=[];String? error;@override void initState(){super.initState();load();}Future<void> load()async{try{final r=await widget.service.list();items=(r['data']??r) as List;}catch(e){error=e.toString();}if(mounted)setState(()=>loading=false);}@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('My Certificates')),body:loading?const Center(child:CircularProgressIndicator()):error!=null?Center(child:Text(error!)):ListView.builder(itemCount:items.length,itemBuilder:(c,i){final x=items[i];return ListTile(leading:const Icon(Icons.workspace_premium_outlined),title:Text(x['course']?['title']??'Course certificate'),subtitle:Text(x['certificate_number']??''));}));}
